			printk("CPU %d: Unknown vmcall %d, RIP: %p\n",
					cpu_data->cpu_id, guest_regs->rax,
					vmcb->rip - X86_INST_LEN_VMCALL);
			guest_regs->rax = -ENOSYS;
			break;
	}
}



